from pathlib import Path
p=Path('src/styles.css')
s=p.read_text()
css='''\n/* LookLiP Finance first-access onboarding */\n.onboarding-backdrop{position:fixed;inset:0;z-index:10000;background:rgba(15,22,35,.46);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);display:grid;place-items:center;padding:18px}.onboarding-card{width:min(620px,100%);max-height:min(760px,92vh);overflow:auto;background:#fff;border:1px solid rgba(255,255,255,.75);border-radius:28px;padding:30px;box-shadow:0 28px 90px rgba(15,22,35,.28);text-align:center}.onboarding-brand{display:inline-flex;align-items:center;gap:9px;margin-bottom:20px}.onboarding-brand .mark{width:42px;height:42px;border-radius:12px;background:#1464ff url('/meu-primeiro-app/looklip-icon.svg') center/cover no-repeat;color:transparent;box-shadow:0 8px 22px rgba(57,114,232,.25)}.onboarding-brand b{display:block;font-size:18px;letter-spacing:-.04em}.onboarding-brand span{display:block;font-size:8px;letter-spacing:.24em;font-weight:800;color:#7b8491}.onboarding-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.12em;font-weight:800;color:var(--blue);margin-bottom:8px}.onboarding-card h1{font-size:27px;line-height:1.08;letter-spacing:-.045em;margin:0 auto 10px;max-width:500px}.onboarding-intro{font-size:13px;line-height:1.55;color:#697384;margin:0 auto 22px;max-width:510px}.onboarding-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;text-align:left;margin-bottom:20px}.onboarding-grid>div{border:1px solid #e9edf2;background:#fbfcfd;border-radius:14px;padding:13px}.onboarding-grid>div:last-child{grid-column:1/-1}.onboarding-grid strong{display:block;font-size:12px;margin-bottom:5px}.onboarding-grid span{display:block;color:#697384;font-size:10px;line-height:1.4}.onboarding-start{width:100%;font-weight:800;min-height:48px;margin-bottom:8px}.onboarding-card>small{display:block;color:#9aa2ad;font-size:9px}@media(max-width:520px){.onboarding-backdrop{padding:10px;align-items:end}.onboarding-card{max-height:92vh;border-radius:24px;padding:22px 16px calc(18px + env(safe-area-inset-bottom))}.onboarding-brand{margin-bottom:14px}.onboarding-card h1{font-size:23px}.onboarding-intro{font-size:12px;margin-bottom:16px}.onboarding-grid{gap:7px;margin-bottom:15px}.onboarding-grid>div{padding:10px;border-radius:12px}.onboarding-grid strong{font-size:11px}.onboarding-grid span{font-size:9px}.onboarding-start{font-size:13px}}\n'''
if '.onboarding-backdrop{' not in s:
    s += css
p.write_text(s)
print('Onboarding styles applied')
